import {useEffect,useState} from 'react';import {RefreshCw,ShieldCheck,Sparkles} from 'lucide-react';import {createAiDraft,getAiCopilotStatus} from '../../lib/practiceOperationsApi';
export function ExternalAiCopilot({clients=[]}){const[data,setData]=useState(null),[state,setState]=useState('loading'),[error,setError]=useState(''),[form,setForm]=useState({client_id:'',purpose:'DRAFT',instruction:'',source_references:[]}),[result,setResult]=useState(null);const load=async()=>{setState('loading');setError('');try{setData(await getAiCopilotStatus());setState('ready')}catch(reason){setError(reason.message||'AI Copilot status could not be loaded.');setState('error')}};useEffect(()=>{void load()},[]);const submit=async e=>{e.preventDefault();setError('');try{setResult(await createAiDraft({...form,client_id:form.client_id||null}))}catch(reason){setError(reason.message||'AI draft could not be prepared.')}};return <section className="space-y-5"><header><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Assistive intelligence</p><h2 className="mt-1 text-3xl font-bold">AI Practice Copilot</h2><p className="mt-2 text-sm text-slate-600">Draft, summarise, prepare, and suggest—with mandatory human review and no autonomous product actions.</p></header>{state==='loading'?<div aria-label="Loading AI provider" className="h-40 animate-pulse rounded-3xl bg-white"/>:state==='error'?<div className="rounded-3xl border border-red-200 bg-red-50 p-6"><p role="alert">{error}</p><button onClick={load} className="mt-4 min-h-11 rounded-xl border bg-white px-4"><RefreshCw className="mr-2 inline" size={16}/>Retry</button></div>:data.status==='NOT_CONFIGURED'?<article className="rounded-3xl border border-amber-200 bg-amber-50 p-6"><Sparkles/><h3 className="mt-3 text-xl font-bold">AI runtime provider not configured</h3><p className="mt-2 text-sm">No AI output is fabricated. Existing practice operations continue normally.</p><p className="mt-3 text-xs font-semibold"><ShieldCheck className="mr-1 inline" size={15}/>Autonomous actions: NO</p></article>:<form onSubmit={submit} className="rounded-3xl border bg-white p-6"><div className="grid gap-4 sm:grid-cols-2"><label className="text-sm font-semibold">Purpose<select value={form.purpose} onChange={e=>setForm({...form,purpose:e.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3">{['DRAFT','SUMMARISE','PREPARE','SUGGEST'].map(value=><option key={value}>{value}</option>)}</select></label><label className="text-sm font-semibold">Client context (optional)<select value={form.client_id} onChange={e=>setForm({...form,client_id:e.target.value})} className="mt-2 min-h-12 w-full rounded-xl border px-3"><option value="">Practice-wide</option>{clients.map(client=><option key={client.id} value={client.id}>{client.displayName}</option>)}</select></label></div><label className="mt-4 block text-sm font-semibold">Instruction<textarea required value={form.instruction} onChange={e=>setForm({...form,instruction:e.target.value})} className="mt-2 min-h-32 w-full rounded-xl border p-3"/></label><button className="mt-5 min-h-12 rounded-xl bg-blue-700 px-5 font-semibold text-white">Prepare AI draft</button>{result&&<div className="mt-5 rounded-2xl bg-blue-50 p-4"><strong>AI_DRAFT</strong><p className="mt-1 text-sm">Queued for the configured provider. Human review is required before any use.</p></div>}</form>}<aside className="rounded-3xl border bg-slate-950 p-6 text-white"><h3 className="font-bold">Governed boundary</h3><p className="mt-2 text-sm text-slate-300">The Copilot cannot diagnose, prescribe, publish plans or reports, send messages, take payments, or mutate health records.</p></aside></section>}
